def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sep = next((r for r, row in enumerate(grid)
                if all(v == 2 for v in row)), None)
    if sep is None:
        return out

    bg = grid[0][0]
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]
    if not cells:
        return out

    above = all(r < sep for r, c in cells)
    below = all(r > sep for r, c in cells)
    if not (above or below):
        return out

    # Move the colored pattern to the side of the separator, adjacent to it.
    minr = min(r for r, c in cells)
    maxr = max(r for r, c in cells)
    if above:
        shift = (sep - 1) - maxr
    else:
        shift = (sep + 1) - minr

    for r, c in cells:
        out[r][c] = bg
    moved = [(r + shift, c) for r, c in cells]
    for r, c in moved:
        out[r][c] = grid[next(rr for rr, cc in cells if cc == c), c]
    # Mark the row immediately farther from the separator with 8.
    markrow = min(r for r, c in moved) - 1 if above else max(r for r, c in moved) + 1
    if 0 <= markrow < h and markrow != sep:
        out[markrow] = [8] * w
    return out
